export async function nextIssueNumber(orgId: OrgId, projectId: ProjectId): Promise<number> {
  const db = getDb();
  return db.transaction((tx) => {
    const maximum = tx.select({ value: sql<number>"'`coalesce(max(${issues.number}), 0)` })
      .from(issues).where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId))).get()?.value ?? 0;
